import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema, type CreateApiTokenInput } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import { subscribe } from "@/lib/event-bus";

const MAX_USABLE_TOKENS = 5;
const SECRET_PREFIX = "tfk_";

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = toIsoTimestamp(new Date());
  const usable = await apiTokenRepo.countUsableApiTokens(
    parsed.orgId,
    actor.userId,
    now,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} usable API tokens in an organization`,
    );
  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, 12),
    tokenHash: hashToken(token),
    expiresInDays: parsed.expiresInDays,
    createdAt: now,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  if (userId !== actor.userId) {
    assertCan(actor, "api_token:administer", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:administer", orgResource(orgId));
  }

  if (existing.revokedAt !== null) {
    return existing;
  }

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = requireFound(
    await apiTokenRepo.revokeApiToken(orgId, tokenId, revokedAt),
    "ApiToken",
    tokenId,
  );

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * Resolves a bearer token to the actor it may act as. Unknown, revoked,
 * expired, or orphaned tokens resolve to null and leave the row untouched.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!apiToken) return null;
  if (apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (!member) return null;

  await apiTokenRepo.touchLastUsed(apiToken.orgId, apiToken.id, now);

  if (apiToken.scope === "read") {
    return { userId: member.userId, orgId: member.orgId, role: "viewer" };
  }

  return member;
}

/**
 * Revokes every still-live token the removed member holds in that organization.
 * Already-revoked rows keep their original timestamp and are not audited again.
 */
export async function revokeApiTokensForRemovedMember(
  actorId: UserId | null,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const live = await apiTokenRepo.listUnrevokedApiTokens(orgId, userId);
  const revokedAt = toIsoTimestamp(new Date());

  for (const token of live) {
    const revoked = await apiTokenRepo.revokeApiToken(orgId, token.id, revokedAt);
    if (!revoked) continue;

    await emit("api_token.revoked", {
      orgId,
      actorId,
      occurredAt: revokedAt,
      tokenId: revoked.id,
      userId: revoked.userId,
    });
  }
}

export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    if (!hasRoleAtLeast("owner", "viewer")) return;
    await revokeApiTokensForRemovedMember(
      payload.actorId,
      payload.orgId,
      payload.userId,
    );
  });
}

